// Collect results from all table creations
const items = $input.all();
const results = items.map(item => {
  const data = item.json;
  if (data.id) {
    return { table: data.name, id: data.id, status: 'created' };
  } else {
    return { table: data.name || 'unknown', error: data.error || data.message || 'Failed', status: 'error' };
  }
});
return [{ json: { tables: results, summary: `Created ${results.filter(r => r.status === 'created').length} of ${results.length} tables` } }];
